   NULL::text,
   '["品質管理(QC)", "品質保証(QA)", "品質計画", "リスク対応計画"]',
   0,
   '[0]',
   'single',
   '{"asked": "テストによる欠陥検出という活動が、品質マネジメントのどの分類に該当するかを問う設問。", "point": "『成果物そのものを検証し欠陥を見つける』のが品質管理(QC)。プロセスが標準どおり守られているかを確認するのは品質保証(QA)。", "kid": "実際に作ったものを検査して、悪いところを見つける活動。", "eg": "料理でいえば、出来上がった料理を味見して塩加減が合っているか確認するのが品質管理。レシピどおりの手順・分量で作ったかを後から確認するのが品質保証。", "terms": [["品質管理(QC)", "成果物そのものを検証し、要求事項を満たしているか確認する活動"], ["品質保証(QA)", "開発プロセスが定められた標準や手順どおりに実施されているかを確認する活動"]], "think": "なぜテストして欠陥を見つける活動が品質管理に分類されるのかがカギ。品質マネジメントには大きく分けて、成果物そのものを検証する活動と、成果物を作る過程(プロセス)を検証する活動の2種類がある。プログラムを実際に動かしてテストし、欠陥を見つける活動は、出来上がった成果物そのものを検証しているので前者にあたり、これを品質管理(QC)と呼ぶ。一方、決められた手順どおりに開発が進められているかを確認する活動は成果物ではなくプロセスを検証しているので、品質保証(QA)と呼ばれ区別される。", "why_asked": "品質管理(QC)と品質保証(QA)という似た用語を、対象が『成果物』か『プロセス』かで正しく見分けられるかを問う頻出パターン。", "vs": "プロセスが標準どおり実施されているかを確認するのは品質保証。成果物そのものを検証するのは品質管理。テストによる欠陥検出は成果物の検証にあたる。", "opt": ["正解。テストにより成果物であるプログラムそのものを検証し、欠陥を検出する活動は品質管理(QC)に分類される。", "品質保証(QA)は、開発プロセスが標準や手順どおりに実施されているかを確認する活動であり、成果物のテストそのものとは対象が異なる。", "品質計画は、品質の基準や達成方法をあらかじめ定める活動であり、実際にテストして欠陥を検出する活動ではない。", "リスク対応計画は、リスクへの対応方法を定める活動であり、品質マネジメントの分類には含まれない。"]}'),
  ('ap-core-q88', 'プロジェクトマネジメント',
   'プロジェクトの開発プロセスが、定められた標準や手順どおりに実施されているかを監査する活動は、品質マネジメントの分類上どれに該当するか。',
   NULL::text,
   '["品質保証(QA)", "品質管理(QC)", "品質計画", "構成管理"]',
   0,
   '[0]',
   'single',
   '{"asked": "開発プロセスの監査という活動が、品質マネジメントのどの分類に該当するかを問う設問。", "point": "『プロセスが標準どおり守られているかの監査』が品質保証(QA)。成果物そのものの検証は品質管理(QC)と区別する。", "kid": "決められた手順どおりに作業が進められているかを、後からチェックする活動。", "eg": "レシピどおりの手順・分量で調理されたかを、料理を作っている過程で確認するのが品質保証。出来上がった料理を実際に味見するのは品質管理。", "terms": [["品質保証(QA)", "開発プロセスが定められた標準や手順どおりに実施されているかを確認する活動"], ["品質管理(QC)", "成果物そのものを検証し、要求事項を満たしているか確認する活動"]], "think": "なぜプロセスを監査する活動が品質保証に分類されるのかがカギ。決められた手順どおりに開発を進めることは、欠陥の少ない成果物を生み出す土台になる。手順が守られているかを確認せず、出来上がった成果物のテストだけに頼ると、欠陥が見つかるたびに手戻りが発生し、非効率になる。そこで、成果物ができあがる前の段階から、開発プロセス自体が標準どおり実施されているかを監査し、問題があれば早期に是正する活動を品質保証(QA)と呼ぶ。これは出来上がった成果物そのものを検証する品質管理(QC)とは対象が異なる。", "why_asked": "品質保証(QA)と品質管理(QC)の対象の違い(プロセスか成果物か)を、具体的な活動の説明から正しく見分けられるかを問う。", "vs": "成果物そのものを検証するのは品質管理(QC)。品質保証(QA)はプロセスが標準どおり実施されているかを対象とする点で異なる。", "opt": ["正解。開発プロセスが標準や手順どおりに実施されているかを監査する活動は品質保証(QA)に分類される。", "品質管理(QC)は、成果物そのものをテストなどで検証する活動であり、プロセスの監査そのものとは対象が異なる。", "品質計画は、品質の基準や達成方法をあらかじめ定める活動であり、実施状況を後から監査する活動ではない。", "構成管理は、成果物のバージョンや変更を管理する活動であり、プロセスが標準どおり実施されているかの監査とは異なる。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q89', 'サービスマネジメント', 'あるWebサービスでサーバーが突然応答しなくなり、利用者から問い合わせが殺到した。運用チームはまずサーバーを再起動してサービスを平常運転に戻した。この対応が主に該当するプロセスとして、適切なものはどれか。', NULL::text, '["インシデント管理", "問題管理", "変更管理", "サービスレベル管理"]', 0, '[0]', 'single', '{"asked": "障害発生時に、まず復旧させることを最優先にした対応がどのプロセスに該当するかを問うている。", "point": "「まず復旧」を目的にした応急対応はインシデント管理。原因究明は問題管理が別に担当する。", "kid": "インシデント管理は、起きてしまった障害を、とにかく早くいつも通りに戻す係。", "eg": "家電が壊れたとき、応急処置としてブレーカーを上げ直して動かすのがインシデント管理。なぜ壊れたのか分解して調べるのは別の仕事(問題管理)。", "terms": [["インシデント", "サービスの計画外の中断や品質低下のこと。障害そのもの"], ["問題管理", "インシデントの根本原因を突き止め、再発を防ぐプロセス"]], "think": "なぜ復旧作業と原因調査を同じプロセスでやらないのかがカギ。障害が起きている間はサービスが止まっている損失が刻一刻と増えるので、まず優先すべきは原因はともかく早く元に戻すこと。原因を追究してから対応すると復旧が遅れ、利用者の不利益が拡大する。逆に復旧だけして原因を放置すると同じ障害が繰り返される。そこで応急対応と恒久対策を別プロセスとして分け、インシデント管理は速さを、問題管理はなぜ起きたかを追う正確さを、それぞれ目的にする。", "why_asked": "インシデント管理と問題管理を同じものだと思っていると、サーバー再起動のような応急対応の設問で問題管理を選んでしまう。目的(速さか原因究明か)で見分けさせる典型問題。", "vs": "問題管理はなぜ何度もサーバーが落ちるのかを調べて恒久対策を打つプロセスで、この設問のような今すぐ直す場面には出てこない。", "opt": ["正解。サービスを平常状態に戻すことを最優先にする応急対応はインシデント管理の役割。", "問題管理は障害の根本原因を調査し恒久的な再発防止策を検討するプロセスで、その場の復旧作業そのものではない。", "変更管理はIT環境への変更を計画的に承認・実施するプロセスで、緊急復旧の再起動作業を指すものではない。", "サービスレベル管理はSLAで合意した水準の達成状況を継続的に測定・改善するプロセスで、緊急の復旧作業そのものを指すものではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">応急対応と恒久対策は別プロセス</text><text x=\"10\" y=\"38\" fill=\"#3b82f6\" font-size=\"9\" font-weight=\"600\">インシデント管理(速さ優先)</text><rect x=\"8\" y=\"46\" width=\"88\" height=\"26\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"52\" y=\"62\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">障害発生</text><line x1=\"96\" y1=\"59\" x2=\"120\" y2=\"59\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"120,59 114,56 114,62\" fill=\"#60a5fa\"/><rect x=\"122\" y=\"46\" width=\"100\" height=\"26\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"172\" y=\"58\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">ワークアラウンド</text><text x=\"172\" y=\"68\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">(応急対応)</text><line x1=\"222\" y1=\"59\" x2=\"246\" y2=\"59\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"246,59 240,56 240,62\" fill=\"#60a5fa\"/><rect x=\"248\" y=\"46\" width=\"86\" height=\"26\" rx=\"4\" fill=\"#1c2030\" stroke=\"#6ab08d\"/><text x=\"291\" y=\"62\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">復旧</text><text x=\"10\" y=\"98\" fill=\"#c9a04a\" font-size=\"9\" font-weight=\"600\">問題管理(正確さ優先)</text><rect x=\"8\" y=\"106\" width=\"88\" height=\"26\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"52\" y=\"120\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">繰り返す</text><text x=\"52\" y=\"129\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">障害</text><line x1=\"96\" y1=\"119\" x2=\"120\" y2=\"119\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><polygon points=\"120,119 114,116 114,122\" fill=\"#c9a04a\"/><rect x=\"122\" y=\"106\" width=\"100\" height=\"26\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"172\" y=\"118\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">根本原因の</text><text x=\"172\" y=\"128\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">調査</text><line x1=\"222\" y1=\"119\" x2=\"246\" y2=\"119\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><polygon points=\"246,119 240,116 240,122\" fill=\"#c9a04a\"/><rect x=\"248\" y=\"106\" width=\"86\" height=\"26\" rx=\"4\" fill=\"#1c2030\" stroke=\"#6ab08d\"/><text x=\"291\" y=\"116\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">恒久対策</text><text x=\"291\" y=\"126\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">(再発防止)</text></svg>"}'),
  ('ap-core-q90', 'サービスマネジメント', '同じサーバーで1か月に3回、同様の障害が発生した。運用チームは毎回ワークアラウンド(回避策)で応急対応してきたが、今回は障害の発生原因そのものを突き止め、恒久的な対策を実施することにした。この活動が主に該当するプロセスとして、適切なものはどれか。', NULL::text, '["問題管理", "インシデント管理", "変更管理", "サービスデスク"]', 0, '[0]', 'single', '{"asked": "繰り返す障害の根本原因を突き止め、恒久対策を実施する活動がどのプロセスに該当するかを問うている。", "point": "なぜ繰り返すのかを突き止めて恒久対策を打つのは問題管理。応急対応の速さではなく原因究明の正確さが目的。", "kid": "問題管理は、同じ故障が何度も起きる原因を探って、二度と起きないようにする係。", "eg": "家電の応急処置(ブレーカーを上げ直すだけ)を何度も繰り返すのではなく、電気系統を分解して不具合の部品を突き止め交換するのが問題管理にあたる。", "terms": [["ワークアラウンド", "根本原因を解決しないまま、影響を一時的に回避・軽減する処置"], ["既知の誤り", "原因と暫定対処法が判明しているが恒久対策がまだの問題のこと"]], "think": "なぜ応急対応を何度も繰り返すだけでは足りないのかがカギ。ワークアラウンドは症状を一時的に抑えるだけで、原因を放置している。放置したままだと同じ障害が何度も再発し、そのたびに応急対応のコストと利用者への影響が積み重なる。そこで繰り返し発生するインシデントを分析し、根本原因を特定して恒久的な対策(設計変更やパッチ適用など)を打つ。これによって初めて同じ障害の再発を止められる。この原因を突き止めて再発を防ぐ活動が問題管理。", "why_asked": "インシデント管理と問題管理を障害対応でひとまとめに覚えていると、この設問のような場面で区別できない。応急処置の繰り返しか、原因追究による恒久対策かで見分けさせる典型。", "vs": "インシデント管理は起きてしまった障害をとにかく早く復旧させることが目的で、原因を突き止めて恒久対策を打つところまでは踏み込まない。", "opt": ["正解。繰り返す障害の根本原因を特定し、恒久的な再発防止策を実施するのは問題管理の役割。", "インシデント管理はサービスを平常状態に早く戻す応急対応が目的で、根本原因の追究や恒久対策の実施までは担わない。", "変更管理はIT環境への変更を計画的に承認・管理するプロセスで、原因調査そのものを行うプロセスではない。", "サービスデスクは利用者からの問い合わせや障害報告を受け付ける窓口であり、原因調査や恒久対策を自ら実施する組織ではない。"]}'),
  ('ap-core-q91', 'サービスマネジメント', 'インシデント管理と問題管理の目的の違いを説明したものとして、最も適切なものはどれか。', NULL::text, '["インシデント管理はサービスの迅速な復旧を、問題管理は根本原因の特定と再発防止をそれぞれ目的とする。", "インシデント管理は障害の根本原因を特定することを目的とし、問題管理はサービスを迅速に復旧させることを目的とする。", "インシデント管理と問題管理はどちらも根本原因の特定のみを目的とし、対応の速さの違いでは区別されない。", "インシデント管理は変更の承認可否を判断することを目的とし、問題管理はサービスレベルの達成状況を監視することを目的とする。"]', 0, '[0]', 'single', '{"asked": "インシデント管理と問題管理、それぞれの目的の違いを正しく説明した文を選ばせている。", "point": "目的で覚える。インシデント管理は復旧の速さ、問題管理は原因究明の正確さ。", "kid": "早く戻すのがインシデント管理、なぜ起きたか調べるのが問題管理という役割分担。", "eg": "救急医療にたとえると、まず応急処置で命をつなぐ救急医がインシデント管理、退院後に精密検査で病気の原因を突き止める専門医が問題管理。", "terms": [["根本原因", "障害を引き起こしている本質的な要因。表面的な症状の裏にある原因"], ["再発防止", "同じ障害が二度と起きないようにする恒久的な対策"]], "think": "なぜ速さと正確さという異なる目的を1つのプロセスに混ぜないのかがカギ。障害発生中はサービス停止の損失が刻々と増えるので、まず速さを最優先にした対応が要る。一方、原因の特定には調査の時間がかかり、急いで結論を出すと誤った対策を打ってしまう恐れがある。速さと正確さは同時に満たしにくい相反する目的なので、目的ごとにプロセスを分け、インシデント管理は復旧の速さを、問題管理は原因究明の正確さをそれぞれ追求する。", "why_asked": "用語の定義そのものを問う基本問題。目的の取り違え(2番目の選択肢のような入れ替え)が典型的な誤答パターン。", "vs": "2番目の選択肢はインシデント管理と問題管理の目的をそっくり入れ替えたひっかけ。", "opt": ["正解。インシデント管理は復旧の速さ、問題管理は原因究明の正確さを、それぞれ目的とする。", "インシデント管理と問題管理の目的を逆にしている。復旧を急ぐのはインシデント管理、原因を追うのは問題管理。", "対応の速さで区別されないという記述が誤り。インシデント管理は速さを、問題管理は正確さを重視する点で明確に区別される。", "変更の承認可否を判断するのは変更管理、サービスレベルの達成状況を監視するのはサービスレベル管理の役割であり、いずれもここでの説明とは異なる。"]}'),
  ('ap-core-q92', 'サービスマネジメント', '本番環境のシステムに変更を加える際、担当者が独自の判断ですぐに変更を実施するのではなく、変更内容を申請し、影響範囲を評価したうえで承認を得てから実施する体制をとる。このような体制を整えるプロセスとして、適切なものはどれか。', NULL::text, '["変更管理", "インシデント管理", "問題管理", "リリース管理"]', 0, '[0]', 'single', '{"asked": "変更前に申請・影響評価・承認を挟む体制が、どのプロセスに該当するかを問うている。", "point": "変更前に影響評価と承認を挟む体制そのものが変更管理。", "kid": "変更管理は、システムをいじる前に影響を確認してからGOサインを出す係。", "eg": "家のリフォームで、業者が現場判断で勝手に壁を抜くのではなく、事前に図面を見せて構造上問題ないかを確認してから工事に入るのと同じ。", "terms": [["RFC(変更要求)", "システムへの変更を正式に申請する依頼書"], ["CAB(変更諮問委員会)", "影響の大きい変更の可否を審査する会議体"]], "think": "なぜ変更を担当者の独断で即実施させないのかがカギ。1つの変更が一見小さく見えても、他の機能やシステムに予期しない影響(副作用)を及ぼすことがある。無秩序に変更を許すと、影響評価が行われないまま本番環境が書き換わり、変更がきっかけの障害が増える。そこで変更内容を申請させ、影響範囲とリスクを事前に評価し、承認を得たうえで計画的に実施する体制を敷く。これにより変更由来の障害を未然に防げる。", "why_asked": "変更管理を変更作業そのものと誤解しやすい。変更管理は実施ではなく可否判断・統制のプロセスである点を問う。", "vs": "リリース管理は承認された変更を実際に本番環境へ導入する準備・実施を担うプロセスで、変更管理は導入するかどうかを判断する統制の役割。", "opt": ["正解。変更を申請させ、影響評価と承認を経てから実施する体制を整えるのは変更管理の役割。", "インシデント管理は起きてしまった障害を早期に復旧させるプロセスで、変更の事前承認体制とは別の活動。", "問題管理は障害の根本原因を調査し恒久対策を検討するプロセスで、変更の承認可否を判断するものではない。", "リリース管理は承認された変更を本番環境へ実際に導入する準備・実施を担うプロセスで、承認の可否を判断する体制そのものではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">変更管理の承認フロー</text><rect x=\"6\" y=\"60\" width=\"72\" height=\"30\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"42\" y=\"76\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">RFC</text><text x=\"42\" y=\"86\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">(変更要求)</text><line x1=\"78\" y1=\"75\" x2=\"100\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"100,75 94,72 94,78\" fill=\"#60a5fa\"/><rect x=\"102\" y=\"60\" width=\"72\" height=\"30\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"138\" y=\"76\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">影響評価</text><text x=\"138\" y=\"86\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">(リスク確認)</text><line x1=\"174\" y1=\"75\" x2=\"196\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"196,75 190,72 190,78\" fill=\"#60a5fa\"/><rect x=\"198\" y=\"60\" width=\"66\" height=\"30\" rx=\"4\" fill=\"#1c2030\" stroke=\"#3b82f6\"/><text x=\"231\" y=\"76\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">CAB</text><text x=\"231\" y=\"86\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">承認</text><line x1=\"264\" y1=\"75\" x2=\"286\" y2=\"75\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"286,75 280,72 280,78\" fill=\"#60a5fa\"/><rect x=\"288\" y=\"60\" width=\"46\" height=\"30\" rx=\"4\" fill=\"#1c2030\" stroke=\"#6ab08d\"/><text x=\"311\" y=\"79\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">実施</text><text x=\"170\" y=\"120\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">担当者の独断で即実施はしない</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">影響評価と承認を経てから変更する</text></svg>"}'),
  ('ap-core-q93', 'サービスマネジメント', '変更管理における「標準変更」の説明として、最も適切なものはどれか。', NULL::text, '["あらかじめ承認済みの低リスクな定型変更で、都度のCAB審査を経ずに実施できる。", "緊急の障害対応のため、通常の審査手順を省略して即時実施する変更のこと。", "影響が大きいため、CABによる個別の審査を経たうえで実施すると判断された変更。", "変更内容が事前に定義されておらず、実施のたびに新規に審査の要否から検討し直す変更。"]', 0, '[0]', 'single', '{"asked": "変更管理で扱う「標準変更」という分類の性質を正しく説明した文を選ばせている。", "point": "標準変更は事前承認済み・低リスク・定型の三条件がそろった変更で、毎回CAB審査を経ない。", "kid": "標準変更は、もう何度もやって安全とわかっている、いつもの手順通りの変更。", "eg": "会社の経費精算で、少額な定型的な支出は都度上司の決裁を仰がず、あらかじめ決まったルールの範囲内で処理できるのと同じ。", "terms": [["CAB(変更諮問委員会)", "影響の大きい変更の可否を審査する会議体"], ["緊急変更", "重大障害の再発防止などのため通常の審査を待たずに即時実施する変更"]], "think": "なぜリスクの低い変更にまでCAB審査を求めないのかがカギ。CAB審査には人手と時間がかかるので、すべての変更に同じ重さの審査を課すと、リスクの低い定型作業まで滞ってしまい、変更全体のスピードが落ちる。そこで過去に何度も実施して安全性が確認できている手順は、あらかじめ承認済みの標準変更として分類し、都度の個別審査を省略する。一方、リスクが未知・重大な変更は個別に評価する通常変更、緊急時は審査を待たない緊急変更として扱い、リスクの大きさに応じて審査の重さを変える。", "why_asked": "標準変更・通常変更・緊急変更の3分類を混同させる典型問題。特に審査を省略するという共通点だけで標準変更と緊急変更を同一視してしまう誤りが多い。", "vs": "緊急変更は重大障害を止めるため急いで実施するという緊急性が理由で審査を省略するのに対し、標準変更はリスクが低く定型的だから事前承認済みで済むという安全性が理由で審査を省略する。省略の理由が異なる。", "opt": ["正解。標準変更はあらかじめ承認済みでリスクが低い定型的な変更であり、都度のCAB審査を経ずに実施できる。", "これは緊急変更の説明。緊急変更は重大障害対応のため通常の審査手順を待たずに即時実施される。", "これは通常変更の説明。通常変更は個別にCABの審査を経てから実施される、標準・緊急のいずれにも該当しない変更。", "標準変更は実施のたびに手順を新規検討するのではなく、あらかじめ定義された定型的な手順に従う変更である。"]}'),
  ('ap-core-q94', 'サービスマネジメント', '変更管理とリリース管理の役割の違いを説明したものとして、最も適切なものはどれか。', NULL::text, '["変更管理は変更の実施可否を判断・承認し、リリース管理は承認内容を本番環境へ導入する準備と実施を担う。", "変更管理は承認された変更を本番環境へ導入し、リリース管理は変更を実施するかどうかを判断・承認する。", "変更管理とリリース管理はどちらも変更の可否を判断するプロセスであり、実施作業そのものは行わない。", "変更管理は障害の根本原因を調査して恒久対策を検討し、リリース管理はその調査結果をもとに変更の可否を判断する。"]', 0, '[0]', 'single', '{"asked": "変更管理とリリース管理、それぞれの役割の違いを正しく説明した文を選ばせている。", "point": "可否を判断するのが変更管理、実際に導入するのがリリース管理、で覚える。", "kid": "変更管理はGOサインを出す係、リリース管理は実際に運び込んで設置する係。", "eg": "引っ越しにたとえると、変更管理はこの日にこの荷物を運んでよいかを承認する管理会社、リリース管理は実際にトラックで荷物を運び新居に運び込む引っ越し業者。", "terms": [["RFC(変更要求)", "システムへの変更を正式に申請する依頼書"], ["展開管理", "リリース管理が準備した内容を、実際に本番の稼働環境へ配置する工程"]], "think": "なぜ判断と実施を別のプロセスに分けるのかがカギ。判断する人と実施する人が同じだと、実施を急ぐあまり影響評価が甘くなったり、逆に現場の実施都合を優先して承認基準が緩んだりする恐れがある。判断(変更管理)と実施の準備・導入(リリース管理)を分けることで、変更管理はやってよいかをリスクの観点だけで冷静に評価でき、リリース管理は承認された内容を安全に本番環境へ導入する作業に専念できる。役割を分けることで、承認基準と実施品質の両方を保ちやすくなる。", "why_asked": "変更管理とリリース管理を同じ変更に関する作業として一括りにしやすいが、応用情報では判断と実施という役割の違いが問われる。", "vs": "2番目の選択肢は変更管理とリリース管理の役割をそっくり入れ替えたひっかけ。4番目の選択肢は問題管理の役割(根本原因調査)を変更管理に混ぜている。", "opt": ["正解。変更管理は変更の可否を判断・承認し、リリース管理は承認された変更を実際に本番環境へ導入する準備と実施を担う。", "変更管理とリリース管理の役割を逆にしている。可否を判断するのは変更管理、実際に導入するのはリリース管理。", "変更管理もリリース管理も実施作業を行わないという記述が誤り。リリース管理は承認された変更を実際に導入する実施作業を担う。", "根本原因の調査を担うのは問題管理であり、変更管理・リリース管理のいずれの役割でもない。"]}'),
  ('ap-core-q95', 'サービスマネジメント', 'SLA(サービスレベル合意)の説明として、最も適切なものはどれか。', NULL::text, '["サービス提供者と利用者との間で、サービス水準を具体的な指標で取り決めた合意。", "サービス提供者内部の各部門間で、サービスを支える業務分担のルールを取り決めた合意。", "サービス提供者が外部の委託先との間で、業務委託の範囲や料金などを取り決めた契約。", "サービスに関する障害が発生した際に、復旧までの技術的な作業手順を細かく定めた文書。"]', 0, '[0]', 'single', '{"asked": "SLA(サービスレベル合意)が誰と誰の間で交わす、どのような取り決めかを正しく説明した文を選ばせている。", "point": "SLAは提供者と利用者(顧客)の間で交わす、数値で測れるサービス水準の合意。相手が顧客である点が決め手。", "kid": "SLAは、このサービスは応答何秒以内、稼働率何%以上を保証しますという、お店とお客さんの間の約束事。", "eg": "宅配便で注文から翌日までに届けますと約束するのと同じで、サービス提供側が利用者に対して数値で約束するのがSLA。", "terms": [["OLA(運用レベル合意書)", "SLAを達成するために、提供者内部の部門間で交わす合意"], ["UC(請負契約)", "SLA達成のために、外部の委託先と交わす契約"]], "think": "なぜ提供者と利用者の間という当事者を明確にする必要があるのかがカギ。似た合意が社内の部門間(OLA)や外部委託先(UC)とも交わされるため、当事者を区別しないと、これらすべてをSLAと呼んでしまい混同する。SLAはあくまでサービスを実際に使う利用者(顧客)に対して、提供者が何を、どの水準で提供するかを数値で約束したものに限られる。内部の部門間や委託先との合意は、そのSLAを達成するための裏付けとして別に交わされる。", "why_asked": "SLA・OLA・UCの当事者の違いを混同させる典型問題。", "vs": "2番目の選択肢はOLA(提供者内部の部門間合意)、3番目の選択肢はUC(外部委託先との契約)の説明で、いずれもSLAを裏で支える別の合意にすぎない。", "opt": ["正解。SLAはサービス提供者と利用者(顧客)の間で、サービス水準を具体的な指標で取り決めた合意である。", "これはOLA(運用レベル合意書)の説明。提供者内部の部門間の合意であり、利用者との合意ではない。", "これはUC(請負契約)の説明。外部の委託先との契約であり、利用者との合意ではない。", "これは障害復旧の作業手順書の説明であり、サービス水準を数値で取り決める合意であるSLAとは異なる。"]}'),
  ('ap-core-q96', 'サービスマネジメント', 'SLAに記載する内容として、最も適切なものはどれか。', NULL::text, '["サービスの稼働率や対応時間など、あらかじめ合意した測定可能な数値目標。", "サービスを開発した担当エンジニア個人の氏名や、社内での勤務評価。", "サービス提供者が社内で使用しているプログラミング言語やツールの一覧。", "利用者が個人的に感じたサービスへの満足度を自由記述でまとめたアンケート結果。"]', 0, '[0]', 'single', '{"asked": "SLAに記載すべき内容として適切なものを選ばせている。", "point": "SLAに書くのは測定できる数値目標。人事情報や社内ツール一覧、主観的な感想はSLAの対象外。", "kid": "SLAには、稼働率99.9%以上、障害発生から4時間以内に復旧のような、数字で確認できる約束だけを書く。", "eg": "レストランの注文から15分以内に提供しますという掲示のように、後から達成できたかどうかを誰が見ても判定できる数値で約束を書く。", "terms": [["可用性目標", "サービスが利用可能な時間の割合など、稼働に関する数値目標"], ["対応時間", "問い合わせや障害報告を受けてから最初に対応を開始するまでの時間の目標"]], "think": "なぜSLAには数値目標だけを書き、氏名や感想のような情報を書かないのかがカギ。SLAは約束を守れたかどうかを後から客観的に検証できることが前提の合意である。数値目標であれば、実際の稼働率や対応時間を測定し、合意した水準と比較して達成・未達成を機械的に判定できる。一方、個人の勤務評価や主観的な満足度は、測定方法や基準が人によって変わり客観的に検証できないため、合意の対象として不向き。だからSLAには測定可能な数値目標だけを記載する。", "why_asked": "SLAがサービスに関するあらゆる取り決めだと誤解し、無関係な項目を選んでしまう受験者をふるいにかける問題。", "vs": "2番目の選択肢のような個人評価や3番目の選択肢のような社内ツール一覧は、利用者との合意事項ではなく提供者側の内部情報であり、SLAの対象外。", "opt": ["正解。SLAには稼働率や対応時間など、あらかじめ合意した測定可能な数値目標を記載する。", "個人の氏名や勤務評価はサービス水準の合意とは無関係な、提供者内部の人事情報である。", "使用言語やツールの一覧は提供者側の内部実装の詳細であり、利用者と合意すべきサービス水準ではない。", "主観的な満足度アンケートは客観的に達成・未達成を判定できないため、SLAの数値目標としては不適切。"]}'),
  ('ap-core-q97', 'サービスマネジメント', 'SLAを締結した後、サービス提供者が定期的に実績値を測定し、合意した水準を下回った場合に原因を分析して改善策を講じる活動を何と呼ぶか。', NULL::text, '["サービスレベル管理", "インシデント管理", "キャパシティ管理", "ITサービス継続性管理"]', 0, '[0]', 'single', '{"asked": "SLA締結後に実績を測定し改善につなげる継続的な活動の名称を問うている。", "point": "SLA締結後に実績を測り、合意水準と比較し、改善する継続的な活動がサービスレベル管理。", "kid": "サービスレベル管理は、約束(SLA)を結んだ後、ちゃんと守れているか毎回チェックして、守れていなければ手を打つ係。", "eg": "ダイエットの目標体重を決めて終わりにするのではなく、毎週体重を測って、目標を下回ったら食事や運動を見直す、その一連の継続活動がサービスレベル管理にあたる。", "terms": [["モニタリング", "実績値を継続的に測定・記録すること"], ["是正措置", "合意水準を下回った原因を分析し、改善するための対策"]], "think": "なぜSLAを結んだだけで終わらせず、締結後の活動を別に用意するのかがカギ。SLAは約束であって、結んだ瞬間に自動で守られるわけではない。放っておくと実績が水準を下回っていても誰も気づかず、利用者の不満が蓄積してから初めて発覚することになる。そこで締結後も定期的に実績を測定し、合意水準と比較するモニタリングを続け、下回った場合は原因を分析して改善策を講じる。この継続的な活動があって初めてSLAの約束が実際に維持される。", "why_asked": "SLAを結ぶこと自体と、結んだ後に守り続けるための活動を混同させる問題。", "vs": "キャパシティ管理は将来の需要に対して十分な処理能力を確保するための管理で、SLA実績の測定・改善そのものを担うプロセスではない。", "opt": ["正解。SLA締結後に実績を測定し、合意水準との差を分析して改善策を講じる継続的な活動はサービスレベル管理。", "インシデント管理は起きてしまった障害を早期に復旧させる活動であり、SLA実績の定期的な測定・改善とは異なる。", "キャパシティ管理は将来の需要を見越して十分な処理能力を確保する活動であり、SLA実績の監視そのものではない。", "ITサービス継続性管理は災害など重大な事業中断からの復旧計画を整える活動であり、SLA実績の測定・改善を目的とした活動ではない。"]}'),
  ('ap-core-q98', 'サービスマネジメント', '可用性管理の活動として、最も適切なものはどれか。', NULL::text, '["障害を早期に検知する監視体制を整え、機器を冗長化して迅速な復旧体制を構築する。", "サービスの利用者から寄せられた新機能の要望に優先順位を付け、開発スケジュールを決定する。", "システムの利用状況を継続的に分析し、将来必要になるサーバーの増強時期をあらかじめ計画する。", "発生したインシデントを記録し、担当者に割り当てて解決までの対応状況を追跡する。"]', 0, '[0]', 'single', '{"asked": "可用性管理が実際にどのような活動を行うかを問うている。", "point": "可用性管理は止まりにくく、止まってもすぐ戻せるようにする運用上の工夫(監視・冗長化・迅速な復旧体制)が中心。稼働率の計算そのものではない。", "kid": "可用性管理は、サービスができるだけ止まらないように、そして止まってもすぐ元に戻せるように現場を整える係。", "eg": "停電に備えて、電気が止まってもすぐ気づけるようセンサーを付け、非常用発電機を用意し、切り替え手順を訓練しておくようなもの。", "terms": [["冗長化", "同じ機能を持つ機器や経路を複数用意し、一方が故障しても他方で継続できるようにすること"], ["MTTR(平均修理時間)", "故障してから復旧するまでにかかる平均時間。短いほど可用性が高い"]], "think": "なぜ稼働率の数値目標を立てるだけでなく、監視・冗長化・復旧体制という運用上の工夫が必要なのかがカギ。稼働率の目標を決めただけでは、実際に障害が起きたときにどう対応するかが決まっておらず、目標は達成できない。障害の発生自体をゼロにはできないので、まず障害を早期に見つける監視体制を整え、単一の機器が壊れても他系統に切り替えられるよう冗長化しておき、切り替え手順をあらかじめ準備して迅速に復旧できる体制を作る。この3つが揃って初めて、目標とする稼働率を運用として実現できる。", "why_asked": "可用性管理を稼働率を計算するだけの活動と誤解しやすい。実際は監視・冗長化・復旧体制という運用面の工夫が中心であることを問う。", "vs": "4番目の選択肢はインシデント管理(起きた障害の記録・対応追跡)の説明で、可用性管理が担う止まりにくくする仕組み作りとは異なる。", "opt": ["正解。監視体制の整備、機器の冗長化、迅速な復旧体制の構築は、可用性を高く保つための可用性管理の代表的な活動。", "新機能の優先順位付けや開発スケジュールの決定は、可用性管理ではなくシステム開発やプロジェクトマネジメントの活動。", "将来必要な処理能力を見積もり増強時期を計画するのはキャパシティ管理の活動であり、可用性を高める運用上の工夫とは異なる。", "インシデントの記録・割り当て・追跡はインシデント管理の活動であり、障害を未然に防ぐ・素早く戻す仕組み作りである可用性管理とは異なる。"]}'),
  ('ap-core-q99', 'サービスマネジメント', 'システムを構成する重要な機器を二重化し、片方が故障してももう片方に自動的に切り替わるようにしておく設計が、可用性を高める工夫として有効な理由の説明として、最も適切なものはどれか。', NULL::text, '["1台が故障してもサービス全体は止まらず、修理の時間を確保できるから。", "機器を二重化すると、そもそも機器そのものが物理的に故障しなくなるから。", "二重化した機器のうち片方は、稼働率の計算対象から除外してよくなるから。", "二重化することで、障害発生時に原因を調査する作業自体が不要になるから。"]', 0, '[0]', 'single', '{"asked": "機器の二重化(冗長化)が可用性向上に有効な理由を問うている。", "point": "二重化が効くのは壊れなくなるからではなく、1台壊れてもサービスが止まらないから。", "kid": "二重化は、1つ壊れてももう1つが代わりに働き続けられるようにする仕組み。", "eg": "自転車の予備タイヤを積んでおくと、1本パンクしても交換してすぐ走り続けられるのと同じ。パンクしなくなるわけではない。", "terms": [["冗長化(二重化)", "同じ機能を持つ機器を複数用意し、一方が故障しても他方で継続できるようにすること"], ["フェイルオーバー", "主系統が故障した際に、自動的に予備系統へ切り替える仕組み"]], "think": "なぜ二重化すると可用性が上がるのかがカギ。単一の機器構成では、その1台が故障した瞬間にサービス全体が止まってしまう。二重化しておくと、片方が故障してももう片方が処理を引き継ぐため、利用者からはサービスが止まっていないように見える。その間に故障した機器を修理・交換すれば、利用者への影響を出さないまま復旧作業の時間を確保できる。二重化は機器の故障そのものを防ぐわけではなく、1台の故障がサービス全体の停止につながらないようにすることで可用性を高めている。", "why_asked": "冗長化すれば故障しなくなるという誤解を突く問題。仕組みが効く理由(因果)を問う。", "vs": "2番目の選択肢は冗長化の効果を故障しなくなるとすり替えている。実際には故障自体は起こりうるが、その影響をサービス全体に波及させない点が冗長化の本質。", "opt": ["正解。1台の故障がサービス全体の停止に直結しなくなり、利用者への影響を防いだまま修理の時間を確保できる。", "二重化しても個々の機器が故障しなくなるわけではない。故障の発生自体は防げない。", "二重化した機器も両方とも稼働率の計算対象であり、片方を除外してよいという考え方は誤り。", "冗長化は障害発生時のサービス継続を助ける仕組みであり、原因調査を行う問題管理の必要性をなくすものではない。"]}'),
  ('ap-core-q100', 'サービスマネジメント', 'サービスデスクの役割の説明として、最も適切なものはどれか。', NULL::text, '["利用者の問い合わせを受け付ける単一窓口となり、一次対応や他プロセスへ引き継ぐ。", "発生したインシデントの根本原因を調査し、恒久的な再発防止策を実施する。", "IT環境への変更について影響範囲を評価し、実施してよいかどうかの可否を承認する。", "サービスの稼働率や対応時間の実績を測定し、SLAの達成状況を管理する。"]', 0, '[0]', 'single', '{"asked": "サービスデスクが担う役割として適切なものを選ばせている。", "point": "サービスデスクは利用者の窓口(単一窓口)。原因調査・変更承認・SLA管理そのものは別のプロセスが担う。", "kid": "サービスデスクは、困ったことがあったらまずここに連絡する窓口。", "eg": "病院の総合受付のように、患者(利用者)がどんな症状(問い合わせ)でもまずそこに行けば、受付が話を聞いて適切な診療科(担当プロセス)につないでくれる窓口。", "terms": [["単一窓口", "利用者から見て問い合わせ先が1つに統一されている窓口"], ["一次対応", "窓口が受け付けた際にその場で対応できる範囲の初期対応"]], "think": "なぜ利用者の問い合わせ窓口を1つに統一するのかがカギ。窓口がプロセスごとにバラバラだと、利用者はこの障害はどこに連絡すればよいのかを自分で判断しなければならず、連絡先を間違えたり、たらい回しにされたりする。窓口を1つに統一しておけば、利用者はどんな内容でもまずそこに連絡すればよく、受け付けた側が内容を見て一次対応するか、インシデント管理・変更管理など適切なプロセスへ引き継ぐかを判断する。利用者側の負担を減らし、対応漏れも防げる。", "why_asked": "サービスデスクを問い合わせを受けるだけの窓口と軽視し、原因調査や変更承認まで行うと誤解しやすい。役割の境界を問う。", "vs": "2番目の選択肢は問題管理、3番目の選択肢は変更管理、4番目の選択肢はサービスレベル管理の役割であり、いずれもサービスデスクではなく引き継ぎ先の別プロセスが担う。", "opt": ["正解。サービスデスクは利用者からの問い合わせを受け付ける単一の窓口として、一次対応や他プロセスへの引き継ぎを行う。", "根本原因の調査と恒久対策の実施は問題管理の役割であり、サービスデスクが自ら行うものではない。", "変更の可否の評価・承認は変更管理の役割であり、サービスデスクの役割ではない。", "SLA達成状況の測定・管理はサービスレベル管理の役割であり、サービスデスクの役割ではない。"]}'),
  ('ap-core-q101', 'サービスマネジメント', 'サービスデスクが、利用者から寄せられた問い合わせのうち一次対応で解決できない障害を受け付けた場合の対応として、最も適切なものはどれか。', NULL::text, '["インシデントとして記録し、専門知識を持つ二次担当者へエスカレーションする。", "利用者自身に原因を調査してもらうよう案内し、対応した記録は特に残さない。", "変更管理のCABにこの障害を諮り、変更の実施可否として審査してもらう。", "対応が難しいことを理由に、該当する利用者とのSLA契約自体を打ち切る。"]', 0, '[0]', 'single', '{"asked": "サービスデスクが一次対応で解決できない障害を受け付けたときに取るべき対応を問うている。", "point": "サービスデスクが一次対応で解決できなければ、記録してエスカレーションが基本動作。", "kid": "サービスデスクは自分たちで解決できない内容は、抱え込まずに専門の担当者へバトンタッチする。", "eg": "総合受付で対応しきれない込み入った相談を、専門の窓口(担当部署)に案内状を渡して引き継ぐのと同じ。", "terms": [["エスカレーション", "一次対応で解決できない問い合わせを、より専門的な知識を持つ二次対応の担当者へ引き継ぐこと"], ["一次対応", "窓口が受け付けた際にその場で対応できる範囲の初期対応"]], "think": "なぜサービスデスクは自分たちで解決できない問い合わせを抱え込まないのかがカギ。サービスデスクの担当者は幅広い問い合わせに対応する分、個々の技術に深く精通しているとは限らない。無理に自分たちだけで解決しようとすると、対応が長引き利用者を待たせ続けることになる。そこで一次対応で解決できないと判断した時点でインシデントとして記録し、専門知識を持つ二次対応の担当者へエスカレーションする。記録を残すことで、対応の引き継ぎ漏れも防げる。", "why_asked": "サービスデスクが解決できない問い合わせをどう扱うかという運用の基本動作を問う。記録せず放置する誤答が典型的なひっかけ。", "vs": "変更管理のCAB審査は変更の可否を判断する場であり、障害対応のエスカレーション先ではない。", "opt": ["正解。一次対応で解決できない障害はインシデントとして記録し、専門知識を持つ二次対応の担当者へエスカレーションする。", "記録を残さず利用者任せにすると対応状況が追跡できなくなり、対応漏れにつながる。サービスデスクが取るべき対応ではない。", "CABは変更の可否を審査する場であり、一次対応で解決できない障害の引き継ぎ先ではない。", "一次対応で解決できないことを理由にSLA契約自体を打ち切ることは、サービス提供者の対応として不適切。"]}'),
  ('ap-core-q102', 'サービスマネジメント', 'リリース管理と展開管理の役割の違いを説明したものとして、最も適切なものはどれか。', NULL::text, '["リリース管理は変更内容の計画・準備・テストを行い、展開管理は準備済みの内容を本番環境へ導入する。", "リリース管理は本番環境への実際の導入作業を行い、展開管理は導入する内容の計画・準備・テストを行う。", "リリース管理と展開管理はどちらも変更の可否を判断するプロセスであり、実施作業は行わない。", "リリース管理は障害発生時の応急対応を行い、展開管理はその障害の根本原因の調査を行う。"]', 0, '[0]', 'single', '{"asked": "リリース管理と展開管理、それぞれの役割の違いを正しく説明した文を選ばせている。", "point": "計画・準備・テストがリリース管理、実際に本番へ運び込むのが展開管理、で覚える。", "kid": "リリース管理は引っ越しの荷造りと段取り、展開管理は実際にトラックで運んで新居に設置する作業。", "eg": "新商品の発売にたとえると、発売までの企画・生産・検品がリリース管理、実際に店舗に商品を並べる作業が展開管理にあたる。", "terms": [["リリース", "本番環境に導入する準備が整った、変更内容のひとまとまり"], ["展開(デプロイ)", "準備が整ったリリースを、実際の稼働環境へ配置すること"]], "think": "なぜ準備と実際に導入する作業を分けて考えるのかがカギ。変更を承認しただけでは、まだ本番環境で使える状態にはなっていない。テストや導入手順の整備といった準備を怠ったまま本番環境に反映すると、想定外の不具合が利用者に直接影響してしまう。そこで、まずリリース管理として変更内容をひとまとめにし、計画を立ててテストを重ねて品質を確認する。準備が整ったものだけを、展開管理が実際の稼働環境へ導入する。準備工程と導入工程を分けることで、テストが不十分なまま本番に反映される事故を防げる。", "why_asked": "変更管理・リリース管理・展開管理の3つを混同させる問題。特にリリース管理と展開管理はどちらも本番に反映する話に見えるため区別が曖昧になりやすい。", "vs": "変更管理は実施してよいかを判断する統制の役割で、リリース管理・展開管理はその判断の後、実際に変更を形にして届けるまでの実務を担う。", "opt": ["正解。リリース管理は計画・準備・テストを行い、展開管理は準備が整った内容を実際の本番環境へ導入する。", "リリース管理と展開管理の役割を逆にしている。計画・準備・テストがリリース管理、実際の導入作業が展開管理。", "リリース管理・展開管理のいずれも実施作業を行わないという記述は誤り。展開管理は実際に本番環境へ導入する実施作業を担う。", "障害の応急対応はインシデント管理、根本原因の調査は問題管理の役割であり、リリース管理・展開管理のいずれでもない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">承認から本番導入までの3工程</text><rect x=\"4\" y=\"55\" width=\"96\" height=\"34\" rx=\"4\" fill=\"#1c2030\" stroke=\"#3b82f6\"/><text x=\"52\" y=\"70\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">変更管理</text><text x=\"52\" y=\"81\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">(可否を承認)</text><line x1=\"100\" y1=\"72\" x2=\"122\" y2=\"72\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"122,72 116,69 116,75\" fill=\"#60a5fa\"/><rect x=\"124\" y=\"55\" width=\"106\" height=\"34\" rx=\"4\" fill=\"#1c2030\" stroke=\"#2a2f3f\"/><text x=\"177\" y=\"68\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">リリース管理</text><text x=\"177\" y=\"79\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">(計画・準備・テスト)</text><line x1=\"230\" y1=\"72\" x2=\"252\" y2=\"72\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><polygon points=\"252,72 246,69 246,75\" fill=\"#60a5fa\"/><rect x=\"254\" y=\"55\" width=\"82\" height=\"34\" rx=\"4\" fill=\"#1c2030\" stroke=\"#6ab08d\"/><text x=\"295\" y=\"68\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\" font-weight=\"600\">展開管理</text><text x=\"295\" y=\"79\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">(本番へ導入)</text><text x=\"170\" y=\"120\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">「準備」と「実際に導入する作業」は別工程</text><text x=\"170\" y=\"134\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">準備不足のまま本番に出す事故を防ぐ</text></svg>"}'),
  ('ap-core-q103', 'サービスマネジメント', '新しいシステムを全利用者に一度に展開するのではなく、一部の利用者や拠点から順に展開し、問題がないことを確認しながら対象を広げていく展開方式を何と呼ぶか。', NULL::text, '["段階的展開(パイロット展開)", "一括展開(ビッグバン展開)", "緊急変更", "標準変更"]', 0, '[0]', 'single', '{"asked": "一部から順に展開範囲を広げていく展開方式の名称を問うている。", "point": "一部から始めて確認しながら広げるのが段階的展開。全体を一度に切り替えるのが一括展開。", "kid": "段階的展開は、まず一部の教室で新しい教科書を試してから、問題なければ全校に広げるやり方。", "eg": "新しいレジシステムを、まず1店舗だけで試験導入し、問題がないことを確認してから全店舗に広げていくのと同じ。", "terms": [["一括展開(ビッグバン展開)", "全利用者・全拠点に一度に新システムを展開する方式"], ["ロールバック", "展開した変更に問題があった場合、展開前の状態に戻すこと"]], "think": "なぜ全利用者に一度に展開せず、一部から順に広げるのかがカギ。全体に一度に展開すると、想定していなかった不具合があった場合、その影響が全利用者に一気に及んでしまう。段階的展開では、まず影響範囲が限られた一部の利用者や拠点だけに展開し、そこで問題がないことを確認してから対象を広げる。万一問題が見つかっても影響を限られた範囲にとどめられ、必要ならその時点で展開を止めて対処できる。影響範囲をコントロールしながら安全に展開できることが、段階的展開が選ばれる理由。", "why_asked": "展開方式の種類(段階的展開・一括展開)の名称と特徴を問う基本問題。緊急変更・標準変更という変更管理の分類語を紛れ込ませ、展開方式と変更分類を混同させる誤答を作っている。", "vs": "緊急変更・標準変更は変更管理における変更の分類(審査の重さの違い)であり、展開の進め方である段階的展開・一括展開とは別の軸の話。", "opt": ["正解。一部の利用者や拠点から順に展開し、問題がないことを確認しながら対象を広げていく方式を段階的展開(パイロット展開)という。", "一括展開(ビッグバン展開)は全利用者・全拠点に一度に展開する方式であり、順に対象を広げていく方式とは逆の考え方。", "緊急変更は重大障害対応のため通常の審査手順を待たずに即時実施する変更のことで、展開の進め方を指す言葉ではない。", "標準変更はあらかじめ承認済みのリスクの低い定型的な変更のことで、展開の進め方を指す言葉ではない。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
